package main

import (
	"fmt"
	"sync"
)

type result struct {
	job    int
	square int
}

// worker receives jobs until the channel is closed, then returns.
func worker(id int, jobs <-chan int, results chan<- result, wg *sync.WaitGroup) {
	defer wg.Done() // signal this worker finished when the range ends
	for j := range jobs {
		results <- result{job: j, square: j * j} // do work, send outcome
	}
}

func main() {
	const numJobs = 9
	const numWorkers = 5

	jobs := make(chan int, numJobs)      // buffered so the producer never blocks here
	results := make(chan result, numJobs) // buffered so workers never block sending
	var wg sync.WaitGroup

	// Start the fixed pool of workers.
	wg.Add(numWorkers)
	for w := 1; w <= numWorkers; w++ {
		go worker(w, jobs, results, &wg)
	}

	// Producer: send all jobs, then close so workers' range loops end.
	for j := 1; j <= numJobs; j++ {
		jobs <- j
	}
	close(jobs) // ONLY the producer closes jobs, exactly once

	// Coordinator: when every worker has returned, close results.
	go func() {
		wg.Wait()      // wait for all workers to finish
		close(results) // safe to close now; no worker will send again
	}()

	// Consumer: range ends when results is closed and drained.
	sum := 0
	for r := range results {
		sum += r.square
	}
	fmt.Printf("sum of squares 1..%d = %d\n", numJobs, sum)
}

package main

import (
	"context"
	"errors"
	"fmt"
	"runtime"
	"sync"
	"time"
)

type task struct{ id int }
type outcome struct {
	id  int
	err error
}

func process(ctx context.Context, t task) error {
	// Simulate work that respects cancellation.
	select {
	case <-time.After(20 * time.Millisecond):
		if t.id == 7 {
			return errors.New("task 7 failed")
		}
		return nil
	case <-ctx.Done():
		return ctx.Err() // context.Canceled or context.DeadlineExceeded
	}
}

func worker(ctx context.Context, jobs <-chan task, out chan<- outcome, wg *sync.WaitGroup) {
	defer wg.Done()
	for {
		select {
		case <-ctx.Done():
			return // stop promptly on cancel/timeout
		case t, ok := <-jobs:
			if !ok {
				return // jobs closed and drained
			}
			func() {
				defer func() { // recover so one bad job can't kill the worker
					if r := recover(); r != nil {
						out <- outcome{id: t.id, err: fmt.Errorf("panic: %v", r)}
					}
				}()
				out <- outcome{id: t.id, err: process(ctx, t)}
			}()
		}
	}
}

func main() {
	ctx, cancel := context.WithTimeout(context.Background(), 200*time.Millisecond)
	defer cancel() // always release context resources

	numWorkers := runtime.GOMAXPROCS(0)
	jobs := make(chan task)
	out := make(chan outcome, 16)
	var wg sync.WaitGroup

	wg.Add(numWorkers)
	for w := 0; w < numWorkers; w++ {
		go worker(ctx, jobs, out, &wg)
	}

	// Producer respects cancellation while sending.
	go func() {
		defer close(jobs)
		for i := 1; i <= 10; i++ {
			select {
			case jobs <- task{id: i}:
			case <-ctx.Done():
				return // stop feeding if cancelled
			}
		}
	}()

	go func() { wg.Wait(); close(out) }()

	failures := 0
	for o := range out {
		if o.err != nil {
			failures++
		}
	}
	fmt.Printf("workers=%d, failures=%d\n", numWorkers, failures)
}
